(920, 448, 'wcf-dynamic-css', '.cartflows_step-template .select2-container--default .select2-results__option--highlighted[aria-selected], .cartflows_step-template .select2-container--default .select2-results__option--highlighted[data-selected], .wcf-embed-checkout-form { --wcf-primary-color: #131313;--wcf-heading-color: #000000;--wcf-btn-bg-color: #131313;--wcf-btn-bg-hover-color: #000000;--wcf-btn-text-color: #ffffff;--wcf-btn-hover-text-color: #ffffff;--wcf-field-text-color: #8a8a8a;}body .wcf-embed-checkout-form.wcf-embed-checkout-form-instant-checkout { --wcf-primary-color: #131313;--wcf-heading-color: #000000;--wcf-heading-font-weight: 700;--wcf-field-min-height: 33px;--wcf-field-text-color: #8a8a8a;--wcf-btn-bg-color: #131313;--wcf-btn-bg-hover-color: #000000;--wcf-btn-text-color: #ffffff;--wcf-btn-hover-text-color: #ffffff;--wcf-ic-left-column-bg-color: #ffffff;--wcf-ic-right-column-bg-color: #f6f6f6;}\n	.wcf-embed-checkout-form .wcf-checkout-header-image img{\n		width: px;\n	}\n	.wcf-embed-checkout-form .woocommerce #payment input[type=checkbox]:focus,\n	.wcf-embed-checkout-form .woocommerce .woocommerce-shipping-fields [type=\'checkbox\']:focus,\n	.wcf-embed-checkout-form .woocommerce #payment input[type=radio]:checked:focus,\n	.wcf-embed-checkout-form .woocommerce #payment input[type=radio]:not(:checked):focus{\n		box-shadow: 0 0 2px rgba( 19,19,19, .8);\n	}\n\n	.wcf-embed-checkout-form .woocommerce-checkout #payment div.payment_box{\n		background-color: ;\n		font-family: \'Montserrat\', sans-serif;\n	    font-weight: 400;\n	}\n\n	.wcf-embed-checkout-form #add_payment_method #payment div.payment_box::before,\n	.wcf-embed-checkout-form .woocommerce-cart #payment div.payment_box::before,\n	.wcf-embed-checkout-form .woocommerce-checkout #payment div.payment_box::before\n	{\n	    border-bottom-color: ;\n	    border-right-color: transparent;\n	    border-left-color: transparent;\n	    border-top-color: transparent;\n	    position: absolute;\n	}\n\n	.wcf-embed-checkout-form .woocommerce #payment [type=\'radio\']:checked + label,\n	.wcf-embed-checkout-form .woocommerce #payment [type=\'radio\']:not(:checked) + label{\n		font-family: \'Montserrat\', sans-serif;\n	    font-weight: 400;\n	}\n\n	.wcf-embed-checkout-form #order_review .wcf-custom-coupon-field input[type=\'text\'],\n	.wcf-embed-checkout-form .woocommerce form .form-row input.input-text,\n	.wcf-embed-checkout-form .woocommerce form .form-row textarea,\n	.wcf-embed-checkout-form .select2-container--default .select2-selection--single,\n	.wcf-embed-checkout-form .woocommerce form .form-row select.select {\n		border-color: ;\n		padding-top: px;\n		padding-bottom: px;\n		padding-left: px;\n		padding-right: px;\n		min-height: 33px;\n		font-family: \'Montserrat\', sans-serif;\n	    font-weight: 400;\n	}\n\n	.wcf-embed-checkout-form .woocommerce .col2-set .col-1,\n	.wcf-embed-checkout-form .woocommerce .col2-set .col-2,\n	.wcf-embed-checkout-form .woocommerce-checkout .shop_table,\n	.wcf-embed-checkout-form .woocommerce-checkout #order_review_heading,\n	.wcf-embed-checkout-form .woocommerce-checkout #payment,\n	.wcf-embed-checkout-form .woocommerce form.checkout_coupon\n	{\n		background-color: ;\n		border-color: ;\n		font-family: \'Montserrat\', sans-serif;\n	    font-weight: 400;\n	}\n\n\n	.wcf-embed-checkout-form .woocommerce form p.form-row label {\n		font-family: \'Montserrat\', sans-serif;\n	    font-weight: 400;\n	}\n	.wcf-embed-checkout-form .woocommerce form #payment button,\n	.wcf-embed-checkout-form .woocommerce form.woocommerce-form-login .form-row button {\n		padding-top: px;\n		padding-bottom: px;\n		padding-left: px;\n		padding-right: px;\n		border-color: #131313;\n		min-height: 33px;\n		font-family: \'Montserrat\', sans-serif;\n	    font-weight: 400;\n	}\n\n	.wcf-embed-checkout-form .woocommerce #order_review .wcf-custom-coupon-field .wcf-submit-coupon.button{\n		border-color: #131313;\n		min-height: 33px;\n		font-family: \'Montserrat\', sans-serif;\n	    font-weight: 400;\n	}\n	.wcf-embed-checkout-form .woocommerce-checkout form.woocommerce-form-login .button,\n	.wcf-embed-checkout-form .woocommerce-checkout form.checkout_coupon .button{\n		border: 1px #131313 solid;\n		min-height: 33px;\n		font-family: \'Montserrat\', sans-serif;\n	    font-weight: 400;\n	}\n	.wcf-embed-checkout-form .woocommerce-checkout form.login .button:hover,\n	.wcf-embed-checkout-form .woocommerce-checkout form.checkout_coupon .button:hover,\n	.wcf-embed-checkout-form .woocommerce #payment #place_order:hover,\n	.wcf-embed-checkout-form .woocommerce #order_review button.wcf-btn-small:hover,\n	.wcf-embed-checkout-form .woocommerce #order_review .wcf-custom-coupon-field .wcf-submit-coupon.button:hover{\n		border-color: #000000;\n	}\n	.wcf-embed-checkout-form.wcf-embed-checkout-form-modern-checkout .wcf-customer-info-main-wrapper h3,\n	.wcf-embed-checkout-form .woocommerce h3,\n	.wcf-embed-checkout-form .woocommerce h3 span,\n	.wcf-embed-checkout-form .woocommerce-checkout #order_review_heading{\n		font-family: \'Cormorant Garamond\', serif;\n	    font-weight: 700;\n	}\n	.wcf-embed-checkout-form{\n	    font-family: \'Montserrat\', sans-serif;\n	}img.emoji, img.wp-smiley {}\n			.wcf-embed-checkout-form .woocommerce #payment #place_order:before{\n				content: \"e902\";\n				font-family: \"cartflows-icon\" !important;\n				margin-right: 10px;\n				font-size: 16px;\n				font-weight: 500;\n				top: 0px;\n    			position: relative;\n				opacity: 1;\n				display: block;\n			}'),
